import java.lang.reflect.Proxy;
import java.sql.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

/** Bounded fault doubles only; no real network/database failures are claimed. */
public final class JdbcSafetyTests {
    private static int checks;
    private static void check(boolean b){checks++;if(!b)throw new AssertionError("check "+checks);}
    private static Connection connection(SQLException commitFailure,SQLException rollbackFailure,AtomicBoolean effect){
        return (Connection)Proxy.newProxyInstance(JdbcSafetyTests.class.getClassLoader(),new Class<?>[]{Connection.class},(proxy,method,args)->{
            return switch(method.getName()){
                case "commit"->{effect.set(true);if(commitFailure!=null)throw commitFailure;yield null;}
                case "rollback"->{if(rollbackFailure!=null)throw rollbackFailure;yield null;}
                case "close"->null;
                case "isClosed"->false;
                case "toString"->"bounded Connection fault double";
                default->throw new UnsupportedOperationException(method.getName());
            };
        });
    }
    private static ExecutorService pool(boolean interrupted,boolean terminated){
        return (ExecutorService)Proxy.newProxyInstance(JdbcSafetyTests.class.getClassLoader(),new Class<?>[]{ExecutorService.class},(proxy,method,args)->{
            return switch(method.getName()){
                case "shutdownNow"->java.util.List.of();
                case "awaitTermination"->{if(interrupted)throw new InterruptedException("injected close interruption");yield terminated;}
                case "toString"->"bounded executor fault double";
                default->throw new UnsupportedOperationException(method.getName());
            };
        });
    }
    public static void main(String[] args)throws Exception{
        SQLException original=new SQLException("original"),cleanup=new SQLException("rollback failed");
        try(Connection c=connection(null,cleanup,new AtomicBoolean())){
            JdbcSafety.rollbackAfterFailure(c,original);check(original.getSuppressed().length==1);check(original.getSuppressed()[0]==cleanup);
        }
        SQLException same=new SQLException("same instance");
        try(Connection c=connection(null,same,new AtomicBoolean())){JdbcSafety.rollbackAfterFailure(c,same);check(same.getSuppressed().length==0);}
        AtomicBoolean applied=new AtomicBoolean();SQLException commitFailure=new SQLException("response lost");
        try(Connection c=connection(commitFailure,null,applied)){
            try{JdbcSafety.commit(c);throw new AssertionError("expected commit uncertainty");}
            catch(SQLException unknown){
                check("08007".equals(unknown.getSQLState()));check(unknown.getCause()==commitFailure);
                JdbcSafety.rollbackAfterFailure(c,unknown);check(applied.get());check(unknown.getMessage().contains("UNKNOWN"));
            }
        }
        SQLException failedRollback=new SQLException("cannot rollback");
        try(Connection c=connection(commitFailure,failedRollback,new AtomicBoolean())){
            try{JdbcSafety.commit(c);throw new AssertionError();}catch(SQLException unknown){JdbcSafety.rollbackAfterFailure(c,unknown);check(unknown.getSuppressed()[0]==failedRollback);check(unknown.getCause()==commitFailure);}
        }
        AssertionError testFailure=new AssertionError("primary test failure");
        JdbcSafety.closePool(pool(false,false),testFailure);check(testFailure.getSuppressed().length==1);
        AssertionError interruptedPrimary=new AssertionError("keep me");
        JdbcSafety.closePool(pool(true,false),interruptedPrimary);check(interruptedPrimary.getSuppressed()[0] instanceof InterruptedException);check(Thread.interrupted());
        try{JdbcSafety.closePool(pool(true,false),null);throw new AssertionError();}catch(InterruptedException expected){check(Thread.interrupted());}
        try{JdbcSafety.closePool(pool(false,false),null);throw new AssertionError();}catch(IllegalStateException expected){check(expected.getMessage().contains("budget"));}
        JdbcSafety.closePool(pool(false,true),null);check(!Thread.currentThread().isInterrupted());
        RuntimeException bodyFailure=new RuntimeException("primary executor failure");
        AtomicBoolean destroyed=new AtomicBoolean(),unhooked=new AtomicBoolean();
        CompensationExecutor.cleanup(pool(false,false),()->{destroyed.set(true);throw bodyFailure;},()->unhooked.set(true),bodyFailure);
        check(destroyed.get()&&unhooked.get());check(bodyFailure.getSuppressed().length==1);
        RuntimeException destroyFailure=new RuntimeException("destroy failed");unhooked.set(false);
        try{CompensationExecutor.cleanup(pool(false,true),()->{throw destroyFailure;},()->unhooked.set(true),null);throw new AssertionError();}
        catch(RuntimeException expected){check(expected==destroyFailure&&unhooked.get());}
        AssertionError mainFailure=new AssertionError("main failed");unhooked.set(false);
        CompensationExecutor.cleanup(pool(true,false),()->{},()->unhooked.set(true),mainFailure);
        check(mainFailure.getSuppressed()[0] instanceof InterruptedException);check(Thread.interrupted()&&unhooked.get());
        System.out.println("PASS JdbcSafetyTests: "+checks+" bounded fault-double checks; primary failure/suppression/interrupt preserved, COMMIT uncertainty survives rollback. Not real network fault injection.");
    }
}

import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;

public final class TaskTests {
    private static int checks;
    private static void check(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
    private static TaskOrchestrationLab.Input in(String tenant,String request,String document,long version,long deadline,int priority){
        return new TaskOrchestrationLab.Input(tenant,request,document,version,"snapshot-"+version,"a".repeat(64),123,deadline,priority);
    }
    private static void pipeline(TaskOrchestrationLab s,String key,long now)throws Exception{
        for(int n=0;n<4;n++){var t=s.claim(key,"worker",now+n*2,10);check(t!=null,"stage claim");check(s.complete(t,"artifact-"+n,now+n*2+1),"stage commit");}
    }
    public static void main(String[] args)throws Exception{
        Path root=Files.createTempDirectory("task-lab-");Path d=Files.createDirectory(root.resolve("store"));
        Throwable testFailure=null;
        try{
            try(TaskOrchestrationLab s=new TaskOrchestrationLab(d,100,30,3)){
                var input=in("tenant","normal","doc",1,100,1);s.submit(input,0);
                check(s.durableResponsibility(input.key()),"wakeup may only reference durable obligation");
                check(s.submit(input,200).input().equals(input),"replay original receipt after deadline");
                try{s.submit(in("tenant","normal","doc",2,100,1),0);throw new AssertionError();}catch(IllegalArgumentException expected){checks++;}
                pipeline(s,input.key(),1);check(s.get(input.key()).state()==TaskOrchestrationLab.State.SUCCEEDED,"all four stages");
                check(s.document("tenant/doc").publishedArtifact().equals("artifact-3"),"final publication");
                check(s.cancel(input.key(),50)==TaskOrchestrationLab.State.SUCCEEDED,"completion wins before cancellation");
                s.submit(in("tenant","retry","retrydoc",1,100,1),0);var old=s.claim("tenant/retry","one",0,10);
                check(s.retryKnownSafe(old,1,2),"known safe retry");check(s.claim("tenant/retry","two",2,10)==null,"backoff");
                var next=s.claim("tenant/retry","two",3,10);check(next.epoch()>old.epoch()&&next.operationId().equals(old.operationId()),"stable operation across attempts");
                check(!s.complete(old,"stale",4),"stale attempt rejected");check(s.heartbeat(next,4,10),"renew current token");
                check(!s.heartbeat(old,4,10),"stale heartbeat rejected");
                s.submit(in("tenant","unknown","unknown-doc",1,20,1),0);var uncertain=s.claim("tenant/unknown","one",0,10);
                check(!s.complete(uncertain,"too-late",10),"exact lease boundary");
                var observed=s.get("tenant/unknown");check(s.recover("tenant/unknown",observed.revision(),10),"recovery scanner");
                check(s.claim("tenant/unknown","two",10,10)==null,"UNKNOWN cannot blindly rerun");
                check(!s.reconcile("tenant/unknown",uncertain.epoch()+1,TaskOrchestrationLab.Receipt.NOT_STARTED_AND_FENCED,"",10),"wrong reconciliation epoch");
                check(s.reconcile("tenant/unknown",uncertain.epoch(),TaskOrchestrationLab.Receipt.NOT_STARTED_AND_FENCED,"",10),"trusted fence proof");
                var c=s.claim("tenant/unknown","two",11,4);check(c!=null&&c.epoch()==2,"new owner after proof");
                check(s.cancel("tenant/unknown",12)==TaskOrchestrationLab.State.CANCEL_REQUESTED,"running cancellation is a request");
                check(!s.complete(c,"late-output",12),"cancel rejects ordinary late completion");
                check(s.reconcile("tenant/unknown",c.epoch(),TaskOrchestrationLab.Receipt.SUCCEEDED,"late-output",13),"record remote result during cancel");
                check(s.get("tenant/unknown").state()==TaskOrchestrationLab.State.CANCELLED,"publication cancelled");
                check(s.document("tenant/unknown-doc").publishedArtifact().isEmpty(),"cancelled artifact never published");
                s.submit(in("tenant","v1","mutable",1,100,1),0);var v1=s.claim("tenant/v1","one",1,10);
                s.submit(in("tenant","v2","mutable",2,100,1),2);check(!s.complete(v1,"old",3),"superseded document generation");
                s.deleteDocument("tenant/mutable",3);check(s.claim("tenant/v2","two",4,10)==null,"tombstone prevents resurrection");
                s.submit(in("tenant","expiry","expires",1,5,1),0);
                var t=s.get("tenant/expiry");check(s.recover(t.input().key(),t.revision(),5),"queued deadline");
                check(s.get("tenant/expiry").state()==TaskOrchestrationLab.State.EXPIRED,"expiry is durable terminal, not deletion");
                s.submit(in("tenant","race","race-doc",1,100,1),0);
                ExecutorService pool=Executors.newFixedThreadPool(4);
                Throwable poolFailure=null;
                try{
                    List<Callable<Boolean>> jobs=new ArrayList<>();for(int i=0;i<30;i++)jobs.add(()->s.claim("tenant/race","racer",1,10)!=null);
                    int wins=0;for(Future<Boolean> f:pool.invokeAll(jobs,5,TimeUnit.SECONDS))if(f.get())wins++;
                    check(wins==1,"30 competing claims, one owner");
                }catch(Exception|Error failure){poolFailure=failure;throw failure;}finally{JdbcSafety.closePool(pool,poolFailure);}
                AtomicLong now=new AtomicLong(50);
                CompensationJobContract job=new CompensationJobContract(new CompensationJobContract.LocalPort(s),now::get,System::nanoTime);
                int inspected=0;for(int n=0;n<12;n++)inspected+=job.run(0,1,2,2,1_000_000_000L).inspected();
                check(inspected>0&&s.get("tenant/race").state()==TaskOrchestrationLab.State.UNKNOWN,"bounded cursor eventually reaches expired owner");
                Thread.currentThread().interrupt();check(job.run(0,1,2,2,1_000_000_000L).interrupted(),"cooperative cancellation");Thread.interrupted();
                s.saveScanCursor("edge","界".repeat(1365)+"x");
                check(s.scanCursor("edge").getBytes(java.nio.charset.StandardCharsets.UTF_8).length==4096,"exact byte boundary accepted");
                s.saveScanCursor("restart","tenant/normal");
                try{s.saveScanCursor("restart","界".repeat(1366));throw new AssertionError("multibyte cursor accepted");}
                catch(IllegalArgumentException expected){check(s.scanCursor("restart").equals("tenant/normal"),"UTF-8 byte bound before append");}
                try{s.saveScanCursor("restart",null);throw new AssertionError("null cursor accepted");}
                catch(NullPointerException expected){check(s.scanCursor("restart").equals("tenant/normal"),"null rejected before append");}
                try{s.saveScanCursor("restart","x".repeat(4097));throw new AssertionError("oversize cursor accepted");}
                catch(IllegalArgumentException expected){check(s.scanCursor("restart").equals("tenant/normal"),"oversize rejected before durable mutation");}
                try{s.saveScanCursor("restart","\uD800");throw new AssertionError("invalid Unicode cursor accepted");}
                catch(java.nio.charset.CharacterCodingException expected){check(s.scanCursor("restart").equals("tenant/normal"),"invalid encoding rejected before append");}
            }
            try(TaskOrchestrationLab s=new TaskOrchestrationLab(d,100,30,3)){
                check(s.get("tenant/normal").state()==TaskOrchestrationLab.State.SUCCEEDED,"restart retains completion");
                check(s.get("tenant/race").state()==TaskOrchestrationLab.State.UNKNOWN,"restart retains unknown responsibility");
                check(s.scanCursor("restart").equals("tenant/normal"),"persistent recovery cursor");
                check(s.scanCursor("edge").equals("界".repeat(1365)+"x"),"byte boundary survives reopen after rejected writes");
                check(s.document("tenant/mutable").deleted(),"durable tombstone");
            }
            Path cap=Files.createDirectory(root.resolve("capacity"));
            try(TaskOrchestrationLab s=new TaskOrchestrationLab(cap,2,1,2)){
                s.submit(in("a","r","d",1,10000,2),0);
                try{s.submit(in("a","other","e",1,10000,2),0);throw new AssertionError();}catch(IllegalStateException expected){checks++;}
                s.submit(in("b","r","d",1,10000,0),0);
                TaskOrchestrationLab.FairGate gate=new TaskOrchestrationLab.FairGate(2,1);
                var one=gate.choose(s.snapshot(),1);check(one!=null,"first permit");var two=gate.choose(s.snapshot(),1);
                check(two!=null&&two.task().input().priority()==0,"P0 reserved permit");check(gate.choose(s.snapshot(),1)==null,"bounded in flight");
                gate.release(one);gate.release(one);gate.release(two);check(gate.inFlight()==0,"idempotent release");
                TaskOrchestrationLab.FairGate single=new TaskOrchestrationLab.FairGate(1,0);
                var stalePermit=single.choose(s.snapshot(),1);single.release(stalePermit);
                var currentPermit=single.choose(List.of(stalePermit.task()),2);
                check(currentPermit!=null,"same task can acquire again");single.release(stalePermit);
                check(single.inFlight()==1&&single.choose(s.snapshot(),2)==null,"stale release cannot remove new permit");
                single.release(currentPermit);single.release(currentPermit);check(single.inFlight()==0,"exact permit release remains idempotent");
            }
            try{in("t","r","d",1,1,0);new TaskOrchestrationLab.Input("t","r","d",1,"s","a".repeat(64),128L*1024*1024+1,1,0);throw new AssertionError();}
            catch(IllegalArgumentException expected){checks++;}
            System.out.println("PASS TaskTests: "+checks+" bounded checks; durable four-stage state, replay, lease, UNKNOWN, cancellation, generation, scanner, fairness. No broker/model/XXL cluster.");
        }catch(Exception|Error failure){testFailure=failure;throw failure;}finally{FailureTools.cleanup(testFailure, () -> {JournalTests.delete(root);});}
    }
}

import java.sql.*;
import java.util.*;
import java.util.concurrent.*;

/** Local routing property tests plus real H2 slot/outbox/fencing transactions. */
public final class AlarmSlots {
    private final String url;
    public AlarmSlots(String url)throws SQLException {
        this.url=url;
        try(Connection c=open();Statement s=c.createStatement()){
            s.execute("CREATE TABLE IF NOT EXISTS rule(id INT PRIMARY KEY, version INT, next_slot BIGINT)");
            s.execute("CREATE TABLE IF NOT EXISTS run(rule_id INT, version INT, slot BIGINT, epoch BIGINT, done BOOLEAN, PRIMARY KEY(rule_id,version,slot))");
            s.execute("CREATE TABLE IF NOT EXISTS outbox(rule_id INT, version INT, slot BIGINT, PRIMARY KEY(rule_id,version,slot))");
        }
    }
    private Connection open()throws SQLException{return DriverManager.getConnection(url);}
    public void seed()throws SQLException{try(Connection c=open();Statement s=c.createStatement()){s.execute("INSERT INTO rule VALUES(1,1,0)");}}
    // Bounded catch-up: persist up to maxSlots; later calls continue from the same cursor.
    public int emit(long through,int maxSlots,boolean fail)throws SQLException{
        if(through<0||maxSlots<=0||maxSlots>1000)throw new IllegalArgumentException();
        try(Connection c=open()){
            c.setAutoCommit(false);
            try{
                long next;int version;
                try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT version,next_slot FROM rule WHERE id=1 FOR UPDATE")){r.next();version=r.getInt(1);next=r.getLong(2);}
                int emitted=0;
                while(next<=through&&emitted<maxSlots){
                    try(PreparedStatement p=c.prepareStatement("INSERT INTO run VALUES(1,?,?,0,FALSE)")){p.setInt(1,version);p.setLong(2,next);p.executeUpdate();}
                    try(PreparedStatement p=c.prepareStatement("INSERT INTO outbox VALUES(1,?,?)")){p.setInt(1,version);p.setLong(2,next);p.executeUpdate();}
                    next=Math.incrementExact(next);emitted++;
                }
                if(fail)throw new SQLException("injected rollback");
                try(PreparedStatement p=c.prepareStatement("UPDATE rule SET next_slot=? WHERE id=1")){p.setLong(1,next);p.executeUpdate();}
                JdbcSafety.commit(c);return emitted;
            }catch(SQLException|RuntimeException e){JdbcSafety.rollbackAfterFailure(c,e);throw e;}
        }
    }
    // Explicit administrative/lease authority takeover; lease timing is outside this sample.
    public long takeOver(long slot)throws SQLException{
        try(Connection c=open()){
            c.setAutoCommit(false);
            try{
                try(PreparedStatement p=c.prepareStatement("UPDATE run SET epoch=epoch+1 WHERE rule_id=1 AND version=1 AND slot=? AND done=FALSE")){p.setLong(1,slot);if(p.executeUpdate()!=1){c.rollback();return -1;}}
                try(PreparedStatement p=c.prepareStatement("SELECT epoch FROM run WHERE rule_id=1 AND version=1 AND slot=?")){p.setLong(1,slot);try(ResultSet r=p.executeQuery()){r.next();long e=r.getLong(1);JdbcSafety.commit(c);return e;}}
            }catch(SQLException|RuntimeException e){JdbcSafety.rollbackAfterFailure(c,e);throw e;}
        }
    }
    public boolean complete(long slot,long epoch)throws SQLException{
        try(Connection c=open();PreparedStatement p=c.prepareStatement("UPDATE run SET done=TRUE WHERE rule_id=1 AND version=1 AND slot=? AND epoch=? AND done=FALSE")){p.setLong(1,slot);p.setLong(2,epoch);return p.executeUpdate()==1;}
    }
    static int shard(long rule){return Math.floorMod(Long.hashCode(rule),1024);}
    public long count(String sql)throws SQLException{try(Connection c=open();Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){r.next();return r.getLong(1);}}
    private static void check(boolean b){if(!b)throw new AssertionError();}
    public static void main(String[] args)throws Exception{
        for(int workers:new int[]{1,3,7,19}){
            int[] seen=new int[100000];
            for(int owner=0;owner<workers;owner++)for(int r=0;r<seen.length;r++)if(shard(r)%workers==owner)seen[r]++;
            for(int n:seen)check(n==1);
        }
        // Two topology epochs overlap: a deterministic owner in each view still means two attempts.
        int attempts=0;for(int r=0;r<100000;r++){check(shard(r)>=0&&shard(r)<1024);attempts+=2;}check(attempts==200000);
        if(args.length!=1)throw new IllegalArgumentException("one isolated temporary database path");
        String url="jdbc:h2:"+args[0]+";LOCK_TIMEOUT=3000";AlarmSlots s=new AlarmSlots(url);s.seed();
        try{s.emit(9,4,true);throw new AssertionError();}catch(SQLException e){check(e.getMessage().contains("injected"));}
        check(s.count("SELECT COUNT(*) FROM run")==0&&s.count("SELECT next_slot FROM rule")==0);
        ExecutorService pool=Executors.newFixedThreadPool(8);
        Throwable testFailure=null;
        try{List<Callable<Integer>> tasks=new ArrayList<>();for(int i=0;i<30;i++)tasks.add(()->s.emit(9,4,false));int emitted=0;for(Future<Integer> f:pool.invokeAll(tasks, 10, TimeUnit.SECONDS))emitted+=f.get();check(emitted==10);}catch(Exception|Error failure){testFailure=failure;throw failure;}finally{JdbcSafety.closePool(pool,testFailure);}
        check(s.count("SELECT COUNT(*) FROM run")==10&&s.count("SELECT COUNT(*) FROM outbox")==10&&s.count("SELECT next_slot FROM rule")==10);
        long old=s.takeOver(0),current=s.takeOver(0);check(current==old+1);check(!s.complete(0,old));check(s.complete(0,current));check(!s.complete(0,current));
        AlarmSlots reopened=new AlarmSlots(url);check(reopened.emit(12,2,false)==2);check(reopened.emit(12,2,false)==1);check(reopened.emit(12,2,false)==0);
        check(reopened.count("SELECT COUNT(*) FROM run")==13&&reopened.count("SELECT COUNT(*) FROM outbox")==13);
        System.out.println("PASS AlarmSlots: 100000 rules have one owner per 1/3/7/19-node topology, overlap needs fencing, rollback run+outbox+cursor, 30 racing schedulers emit 10 slots once, stale completion rejected, bounded catch-up/reopen");
    }
}

import java.io.*;
import java.nio.*;
import java.nio.channels.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;
import java.util.zip.CRC32C;

/** Bounded local journal, not a broker. Cooperating single-classloader owners only.
 * Requires local Linux-like filesystem with stable fileKey, advisory locks and directory force.
 * While owned, nobody may replace paths, hard-link segment files or open/close the lock file.
 * No replication, consumer offsets, expiry or automatic repair of complete corrupt frames.
 */
public final class SegmentJournal implements AutoCloseable {
    public static final int MAX_BODY = 1_048_576, MAX_RECORDS = 10_000;
    public static final long MAX_LOG_BYTES = 16L * 1024 * 1024;
    private static final int MAGIC = 0x4A4E4C31, HEADER = 20;
    private record Identity(FileSystem fs, Object key) { }
    private record Owner(Path dir, Identity directory, Identity lockIdentity,
                         FileChannel channel, FileLock lock) { }
    private static final Map<Identity, Owner> OWNERS = new HashMap<>();
    public record Record(long sequence, String id, byte[] payload) {
        public Record { payload = payload.clone(); }
        @Override public byte[] payload() { return payload.clone(); }
    }
    @FunctionalInterface interface Fault { void afterWrite() throws IOException; }
    private final Owner owner;
    private final int segmentBytes;
    private final Fault fault;
    private final LinkedHashMap<String, Record> index = new LinkedHashMap<>();
    private FileChannel active;
    private long bytes;
    private boolean poisoned, closed;

    private static Identity identity(Path p, boolean directory) throws IOException {
        BasicFileAttributes a = Files.readAttributes(p, BasicFileAttributes.class, LinkOption.NOFOLLOW_LINKS);
        if (a.fileKey() == null || (directory ? !a.isDirectory() : !a.isRegularFile()))
            throw new IOException("stable file identity required: " + p);
        return new Identity(p.getFileSystem(), a.fileKey());
    }
    private static void syncDirectory(Path p) throws IOException {
        try (FileChannel c = FileChannel.open(p, StandardOpenOption.READ)) { c.force(true); }
    }
    private static synchronized Owner acquire(Path input) throws IOException {
        // Caller creates its dedicated directory. Resolving symlinks prevents in-JVM directory aliases.
        Path dir = input.toRealPath();
        Identity d = identity(dir, true);
        Path lp = dir.resolve("journal.lock");
        Identity before = Files.exists(lp, LinkOption.NOFOLLOW_LINKS) ? identity(lp, false) : null;
        if (OWNERS.containsKey(d) || (before != null && OWNERS.containsKey(before)))
            throw new IOException("journal already owned in JVM");
        FileChannel c = null;
        FileLock l = null;
        try {
            c = FileChannel.open(lp, StandardOpenOption.CREATE, StandardOpenOption.READ,
                    StandardOpenOption.WRITE, LinkOption.NOFOLLOW_LINKS);
            Identity actual = identity(lp, false);
            if ((before != null && !before.equals(actual)) || OWNERS.containsKey(actual))
                throw new IOException("lock identity changed");
            l = c.tryLock();
            if (l == null) throw new IOException("journal owned by another process");
            syncDirectory(dir);
            Owner o = new Owner(dir, d, actual, c, l);
            OWNERS.put(d, o); OWNERS.put(actual, o);
            return o;
        } catch (IOException | RuntimeException | Error e) {
            // Closing a newly opened alias can release POSIX locks. Alias detection must precede open.
            if (c != null) try { c.close(); } catch (IOException cleanup) { if(e != cleanup)e.addSuppressed(cleanup); }
            throw e;
        }
    }
    private static synchronized void forget(Owner o) {
        OWNERS.remove(o.directory(), o); OWNERS.remove(o.lockIdentity(), o);
    }
    public SegmentJournal(Path dir) throws IOException { this(dir, 2 * 1024 * 1024, () -> { }); }
    public SegmentJournal(Path dir, int segmentBytes) throws IOException { this(dir, segmentBytes, () -> { }); }
    SegmentJournal(Path dir, int segmentBytes, Fault fault) throws IOException {
        if (segmentBytes < 64 || segmentBytes > 2 * 1024 * 1024) throw new IllegalArgumentException("segment size");
        this.segmentBytes = segmentBytes; this.fault = Objects.requireNonNull(fault);
        owner = acquire(dir);
        try { recover(); }
        catch (IOException | RuntimeException | Error e) {
            try { close(); } catch (IOException cleanup) { if(e != cleanup)e.addSuppressed(cleanup); }
            throw e;
        }
    }
    private static int crc(byte[] raw) { CRC32C c = new CRC32C(); c.update(raw); return (int)c.getValue(); }
    static byte[] utf8(String s) throws CharacterCodingException {
        ByteBuffer b = StandardCharsets.UTF_8.newEncoder().onMalformedInput(CodingErrorAction.REPORT)
                .onUnmappableCharacter(CodingErrorAction.REPORT).encode(java.nio.CharBuffer.wrap(s));
        byte[] a = new byte[b.remaining()]; b.get(a); return a;
    }
    private static String decode(byte[] b) throws CharacterCodingException {
        return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT)
                .onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b)).toString();
    }
    private static void readFully(FileChannel c, ByteBuffer b) throws IOException {
        while (b.hasRemaining()) { int n = c.read(b); if (n < 0) throw new EOFException(); if (n == 0) throw new IOException("no read progress"); }
    }
    private static void writeFully(FileChannel c, ByteBuffer b) throws IOException {
        while (b.hasRemaining()) if (c.write(b) <= 0) throw new IOException("no write progress");
    }
    private Path segment(long base) { return owner.dir().resolve(String.format(Locale.ROOT, "%020d.seg", base)); }
    private void createSegment() throws IOException {
        active = FileChannel.open(segment(index.size()), StandardOpenOption.CREATE_NEW,
                StandardOpenOption.READ, StandardOpenOption.WRITE, LinkOption.NOFOLLOW_LINKS);
        active.force(true); syncDirectory(owner.dir());
    }
    private void recover() throws IOException {
        List<Path> paths = new ArrayList<>();
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(owner.dir(), "*.seg")) {
            for (Path p : stream) {
                if (paths.size() >= MAX_RECORDS + 1) throw new IOException("too many segments");
                paths.add(p);
            }
        }
        paths.sort(Comparator.naturalOrder());
        long rawSize = 0;
        for (Path p : paths) {
            String n = p.getFileName().toString();
            if (!n.matches("[0-9]{20}\\.seg")) throw new IOException("bad segment name");
            identity(p, false);
            long size = Files.size(p);
            if (size > segmentBytes) throw new IOException("segment exceeds configured limit");
            rawSize = Math.addExact(rawSize, size);
            if (rawSize > MAX_LOG_BYTES) throw new IOException("journal exceeds byte budget");
        }
        for (int i = 0; i < paths.size(); i++) {
            Path p = paths.get(i);
            long base;
            try { base = Long.parseLong(p.getFileName().toString().substring(0, 20)); }
            catch (NumberFormatException e) { throw new IOException("bad segment base", e); }
            if (base != index.size()) throw new IOException("segment sequence gap");
            boolean last = i == paths.size() - 1;
            try (FileChannel c = FileChannel.open(p, StandardOpenOption.READ, StandardOpenOption.WRITE,
                    LinkOption.NOFOLLOW_LINKS)) {
                long at = 0, size = c.size();
                while (at < size) {
                    if (size - at < HEADER) {
                        // A recognizable older frame must never be mistaken for a v2 torn tail.
                        if (size - at >= 6) {
                            c.position(at); ByteBuffer prefix = ByteBuffer.allocate(6); readFully(c, prefix); prefix.flip();
                            if (prefix.getInt() == MAGIC && prefix.getShort() != 2)
                                throw new IOException("unsupported journal format; explicit migration required");
                        }
                        truncateTail(c, at, last); break;
                    }
                    c.position(at); ByteBuffer h = ByteBuffer.allocate(HEADER).order(ByteOrder.BIG_ENDIAN);
                    readFully(c, h); h.flip();
                    int magic = h.getInt(); short version = h.getShort(), flags = h.getShort();
                    int length = h.getInt(), expected = h.getInt(), headerCrc = h.getInt();
                    // Version 2 checks framing metadata for accidental corruption before trusting length.
                    if (magic != MAGIC || version != 2 || flags != 0 ||
                            crc(Arrays.copyOf(h.array(), HEADER - 4)) != headerCrc ||
                            length < 17 || length > MAX_BODY)
                        throw new IOException("invalid complete frame header");
                    if (size - at - HEADER < length) { truncateTail(c, at, last); break; }
                    byte[] raw = new byte[length]; readFully(c, ByteBuffer.wrap(raw));
                    if (crc(raw) != expected) throw new IOException("CRC mismatch; preserved for diagnosis");
                    ByteBuffer b = ByteBuffer.wrap(raw).order(ByteOrder.BIG_ENDIAN);
                    long seq = b.getLong(); int kl = b.getInt();
                    if (kl < 1 || kl > 1024 || kl > b.remaining() - 4) throw new IOException("bad ID length");
                    byte[] key = new byte[kl]; b.get(key); String id = decode(key);
                    int pl = b.getInt();
                    if (id.isBlank() || pl < 0 || pl != b.remaining() || seq != index.size()
                            || index.containsKey(id) || index.size() >= MAX_RECORDS) throw new IOException("invalid record");
                    byte[] value = new byte[pl]; b.get(value);
                    index.put(id, new Record(seq, id, value)); at += HEADER + (long)length;
                }
                if (!last && c.size() == 0) throw new IOException("empty sealed segment");
                bytes += c.size();
            }
        }
        if (paths.isEmpty()) createSegment();
        else {
            active = FileChannel.open(paths.getLast(), StandardOpenOption.READ, StandardOpenOption.WRITE,
                    LinkOption.NOFOLLOW_LINKS);
            active.position(active.size());
        }
    }
    private static void truncateTail(FileChannel c, long at, boolean last) throws IOException {
        if (!last) throw new IOException("incomplete sealed segment");
        c.truncate(at); c.force(true);
    }
    private void usable() throws IOException {
        if (closed || poisoned) throw new IOException("journal closed or poisoned; reopen and recover");
    }
    public synchronized long append(String id, byte[] input) throws IOException {
        usable();
        if (id == null || id.length() > 1024 || id.isBlank() || input == null) throw new IllegalArgumentException("id/payload");
        byte[] key;
        try { key = utf8(id); } catch (CharacterCodingException e) { throw new IllegalArgumentException("malformed UTF-16 ID", e); }
        long length = 16L + key.length + input.length;
        if (key.length > 1024 || length > MAX_BODY || length + HEADER > segmentBytes)
            throw new IllegalArgumentException("frame too large");
        Record old = index.get(id);
        if (old != null) {
            if (!Arrays.equals(old.payload, input)) throw new IllegalArgumentException("same ID, different payload");
            return old.sequence();
        }
        if (index.size() >= MAX_RECORDS || bytes + HEADER + length > MAX_LOG_BYTES)
            throw new IOException("bounded journal full");
        byte[] value = input.clone(); long seq = index.size();
        ByteBuffer body = ByteBuffer.allocate((int)length).order(ByteOrder.BIG_ENDIAN);
        body.putLong(seq).putInt(key.length).put(key).putInt(value.length).put(value);
        ByteBuffer frame = ByteBuffer.allocate(HEADER + (int)length).order(ByteOrder.BIG_ENDIAN);
        frame.putInt(MAGIC).putShort((short)2).putShort((short)0).putInt((int)length)
                .putInt(crc(body.array()));
        frame.putInt(crc(Arrays.copyOf(frame.array(), HEADER - 4))).put(body.array()).flip();
        try {
            if (active.size() + frame.remaining() > segmentBytes) {
                active.force(true); active.close(); active = null; createSegment();
            }
            writeFully(active, frame); fault.afterWrite(); active.force(true);
            // The index and caller's ACK follow force, never precede it.
            index.put(id, new Record(seq, id, value)); bytes += HEADER + length; return seq;
        } catch (IOException | RuntimeException | Error e) { poisoned = true; throw e; }
    }
    public synchronized byte[] get(String id) throws IOException { usable(); Record r = index.get(id); return r == null ? null : r.payload(); }
    public synchronized int size() throws IOException { usable(); return index.size(); }
    public synchronized List<Record> records() throws IOException {
        usable(); return index.values().stream().map(r -> new Record(r.sequence(), r.id(), r.payload)).toList();
    }
    @Override public synchronized void close() throws IOException {
        if (closed) return;
        closed = true; IOException failure = null;
        if (active != null) {
            try { if (!poisoned) active.force(true); } catch (IOException e) { failure = e; }
            try { active.close(); } catch (IOException e) { if (failure == null) failure = e; else if(failure != e)failure.addSuppressed(e); }
        }
        try { owner.channel().close(); } catch (IOException e) { if (failure == null) failure = e; else if(failure != e)failure.addSuppressed(e); }
        // A cleanup failure keeps the JVM reservation: fail closed rather than create two owners.
        if (failure == null) forget(owner); else throw failure;
    }
}

import java.io.*;
import java.nio.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.zip.CRC32C;

public final class JournalTests {
    private static int checks;
    static void check(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
    @FunctionalInterface interface Action{void run()throws Exception;}
    static void fails(Action a)throws Exception{
        try{a.run();throw new AssertionError("expected rejection");}catch(IOException|IllegalArgumentException expected){checks++;}
    }
    static byte[] b(String s){return s.getBytes(StandardCharsets.UTF_8);}
    static Path dir(Path root,String name)throws IOException{return Files.createDirectory(root.resolve(name));}
    static Path first(Path d)throws IOException{try(var s=Files.list(d)){return s.filter(p->p.toString().endsWith(".seg")).sorted().findFirst().orElseThrow();}}
    static void delete(Path p)throws IOException{try(var s=Files.walk(p)){for(Path x:s.sorted(Comparator.reverseOrder()).toList())Files.delete(x);}}
    static void childDenied(Path d)throws Exception{
        Process p=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin","java").toString(),"-Xmx64m","-cp",
                System.getProperty("java.class.path"),"JournalTests","probe",d.toString()).redirectErrorStream(true).start();
        Throwable childFailure=null;
        try{if(!p.waitFor(5,TimeUnit.SECONDS))throw new AssertionError("child timeout");check(p.exitValue()==0,"child must reject active owner: "+new String(p.getInputStream().readAllBytes(),StandardCharsets.UTF_8));}
        catch(Exception|Error failure){childFailure=failure;throw failure;}
        finally{
            Throwable failure=childFailure;
            try{if(p.isAlive()){p.destroyForcibly();if(!p.waitFor(5,TimeUnit.SECONDS))throw new IOException("child remains");}}
            catch(Exception|Error next){if(failure==null)failure=next;else FailureTools.attach(failure,next);}
            for(AutoCloseable stream:List.of(p.getInputStream(),p.getErrorStream(),p.getOutputStream())){
                try{stream.close();}catch(Exception|Error next){if(failure==null)failure=next;else FailureTools.attach(failure,next);}
            }
            if(childFailure==null&&failure!=null){if(failure instanceof Exception e)throw e;throw (Error)failure;}
        }
    }
    public static void main(String[] args)throws Exception{
        if(args.length>0&&args[0].equals("probe")){
            try(SegmentJournal j=new SegmentJournal(Path.of(args[1]))){j.size();System.exit(3);}
            catch(IOException expected){return;}
        }
        Path root=Files.createTempDirectory("journal-lab-");
        Throwable testFailure=null;
        try{
            Path d=dir(root,"main");
            try(SegmentJournal j=new SegmentJournal(d)){
                byte[] a=b("hello");check(j.append("租户",a)==0,"first");a[0]=0;
                check(Arrays.equals(j.get("租户"),b("hello")),"input cloned");
                byte[] result=j.get("租户");result[0]=1;check(Arrays.equals(j.get("租户"),b("hello")),"output cloned");
                check(j.append("租户",b("hello"))==0,"idempotent");fails(()->j.append("租户",b("different")));
                fails(()->j.append("\uD800",b("x")));fails(()->j.append(" ",b("x")));fails(()->j.append("x".repeat(1025),new byte[0]));
                fails(()->j.append("large",new byte[SegmentJournal.MAX_BODY]));
                ExecutorService pool=Executors.newFixedThreadPool(4);
                Throwable poolFailure=null;
                try{
                    List<Callable<Long>> jobs=new ArrayList<>();for(int i=0;i<30;i++)jobs.add(()->j.append("same",b("same")));
                    for(Future<Long> f:pool.invokeAll(jobs,5,TimeUnit.SECONDS))check(f.get()==1,"duplicate race");
                    jobs.clear();for(int i=0;i<30;i++){int n=i;jobs.add(()->j.append("unique-"+n,b("v"+n)));}
                    Set<Long> seq=new HashSet<>();for(Future<Long> f:pool.invokeAll(jobs,5,TimeUnit.SECONDS))seq.add(f.get());
                    check(seq.size()==30&&j.size()==32,"unique race");
                }catch(Exception|Error failure){poolFailure=failure;throw failure;}finally{JdbcSafety.closePool(pool,poolFailure);}
                fails(()->{try(SegmentJournal other=new SegmentJournal(d)){other.size();}});childDenied(d);
                Path symlink=root.resolve("alias");Files.createSymbolicLink(symlink,d);
                fails(()->{try(SegmentJournal other=new SegmentJournal(symlink)){other.size();}});childDenied(d);
                Path hard=dir(root,"hard");Files.createLink(hard.resolve("journal.lock"),d.resolve("journal.lock"));
                fails(()->{try(SegmentJournal other=new SegmentJournal(hard)){other.size();}});childDenied(d);
            }
            SegmentJournal old=new SegmentJournal(d);check(old.size()==32,"rebuild index");old.close();
            try(SegmentJournal fresh=new SegmentJournal(d)){old.close();check(fresh.size()==32,"old close cannot remove new owner");childDenied(d);}
            fails(()->old.append("closed",b("x")));
            Path sample=dir(root,"sample");long prefix;
            try(SegmentJournal j=new SegmentJournal(sample)){j.append("a",b("one"));prefix=Files.size(first(sample));j.append("b",b("two"));}
            byte[] full=Files.readAllBytes(first(sample));
            for(int cut=(int)prefix;cut<full.length;cut++){
                Path c=dir(root,"tail-"+cut);Files.write(c.resolve("00000000000000000000.seg"),Arrays.copyOf(full,cut));
                try(SegmentJournal j=new SegmentJournal(c)){check(j.size()==1,"tail record count");check(Files.size(first(c))==prefix,"truncate incomplete last frame");check(j.append("b",b("two"))==1,"reappend stable sequence");}
            }
            Path corrupt=dir(root,"corrupt");Path cf=corrupt.resolve("00000000000000000000.seg");
            byte[] bad=full.clone();bad[bad.length-1]^=1;Files.write(cf,bad);
            fails(()->{try(SegmentJournal j=new SegmentJournal(corrupt)){j.size();}});check(Arrays.equals(Files.readAllBytes(cf),bad),"CRC refusal preserves bytes");
            Files.write(cf,full);try(SegmentJournal j=new SegmentJournal(corrupt)){check(j.size()==2,"constructor failure releases owner");}
            for(int field:new int[]{0,4,8}){
                byte[] broken=full.clone();broken[field]^=0x7f;Files.write(cf,broken);
                fails(()->{try(SegmentJournal j=new SegmentJournal(corrupt)){j.size();}});
                check(Arrays.equals(Files.readAllBytes(cf),broken),"header refusal preserves bytes");
            }
            // A complete frame with a recomputed CRC but invalid sequence must still be rejected.
            byte[] badSeq=full.clone();ByteBuffer.wrap(badSeq).putLong(20,9);
            int len=ByteBuffer.wrap(badSeq).getInt(8);CRC32C crc=new CRC32C();crc.update(badSeq,20,len);ByteBuffer.wrap(badSeq).putInt(12,(int)crc.getValue());
            CRC32C headerCrc=new CRC32C();headerCrc.update(badSeq,0,16);ByteBuffer.wrap(badSeq).putInt(16,(int)headerCrc.getValue());
            Files.write(cf,badSeq);fails(()->{try(SegmentJournal j=new SegmentJournal(corrupt)){j.size();}});
            // A valid-range corrupted length must not silently discard an acknowledged last frame.
            byte[] changedLength=Arrays.copyOf(full,(int)prefix);
            ByteBuffer.wrap(changedLength).putInt(8,ByteBuffer.wrap(changedLength).getInt(8)+1);
            Files.write(cf,changedLength);fails(()->{try(SegmentJournal j=new SegmentJournal(corrupt)){j.size();}});
            check(Arrays.equals(Files.readAllBytes(cf),changedLength),"bad header length preserves acknowledged bytes");
            byte[] legacy=new byte[17];ByteBuffer.wrap(legacy).putInt(0x4A4E4C31).putShort((short)1);
            Files.write(cf,legacy);fails(()->{try(SegmentJournal j=new SegmentJournal(corrupt)){j.size();}});
            check(Arrays.equals(Files.readAllBytes(cf),legacy),"old format never silently truncated as v2 tail");
            Path rotated=dir(root,"rotated");
            try(SegmentJournal j=new SegmentJournal(rotated,64)){for(int i=0;i<4;i++)j.append("id"+i,new byte[20]);}
            try(SegmentJournal j=new SegmentJournal(rotated,64)){check(j.size()==4,"rotation replay");check(j.append("id2",new byte[20])==2,"dedup across segments");}
            Path sealed=first(rotated);byte[] sealedBytes=Files.readAllBytes(sealed);Files.write(sealed,Arrays.copyOf(sealedBytes,sealedBytes.length-1));
            fails(()->{try(SegmentJournal j=new SegmentJournal(rotated,64)){j.size();}});check(Files.size(sealed)==sealedBytes.length-1,"never truncate sealed segment");
            Path fault=dir(root,"fault");AtomicInteger times=new AtomicInteger();
            try(SegmentJournal j=new SegmentJournal(fault,1024,()->{if(times.getAndIncrement()==0)throw new IOException("injected before force");})){
                fails(()->j.append("uncertain",b("x")));fails(()->j.append("other",b("y")));
            }
            try(SegmentJournal j=new SegmentJournal(fault,1024)){check(j.size()==1&&j.append("uncertain",b("x"))==0,"unknown append recovered, not blindly repeated");}
            Path huge=dir(root,"huge");Path hf=huge.resolve("00000000000000000000.seg");
            try(var raf=new RandomAccessFile(hf.toFile(),"rw")){raf.setLength(SegmentJournal.MAX_LOG_BYTES+1);}
            fails(()->{try(SegmentJournal j=new SegmentJournal(huge)){j.size();}});
            for(int n=0;n<10;n++){try(SegmentJournal j=new SegmentJournal(d)){check(j.size()==32,"repeated clean close/reopen");}}
            System.out.println("PASS JournalTests: "+checks+" bounded checks; local file/locks/rotation/tail/CRC/poison/cleanup. No power loss or replicas.");
        }catch(Exception|Error failure){testFailure=failure;throw failure;}finally{FailureTools.cleanup(testFailure, () -> {delete(root);check(!Files.exists(root),"temporary files cleaned");});}
    }
}
